import pandas as pd

def target_encode(df, cat_col, target_col):
    group_sum = df.groupby(cat_col)[target_col].transform("sum")
    group_count = df.groupby(cat_col)[target_col].transform("count")
    # exclude each row's own label from the statistic used to encode it
    return (group_sum - df[target_col]) / (group_count - 1)

df = pd.DataFrame({
    "product_id": ["P1", "P1", "P1", "P2", "P2", "P2"],
    "churned": [0, 0, 1, 0, 0, 0],
})

df["product_id_encoded"] = target_encode(df, "product_id", "churned")
print(df["product_id_encoded"].tolist())   # [0.5, 0.5, 0.0, 0.0, 0.0, 0.0]
